// Readiness before a critical task (src/readiness.js) and the critical tasks of the crew's own mission (src/mission.js):
// the made-up example tasks and who does them, the 24-hour window, last night's sleep against the short-night draft,
// the kit list's sleep and sedating medicines in the window with the FDA label's 8 hours for zolpidem, the reaction test
// against the person's own runs, when the card asks for the test, the plain words and their sources, and the message to
// the flight surgeon as the server checks it. Code generated by Claude (Anthropic), an AI system.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import {
  READINESS_RULES, READINESS_SOURCES, TASK_KINDS, EXAMPLE_TASKS, MEDICINE_NOTES, exampleTasks, calendarItems, tasksFor, upcomingTasks,
  nextTask, readinessDue, readiness, readinessLines, readinessMessage, medicineText, startsIn, startsInAt, taskName, taskThe,
} from '../src/readiness.js';
import { taskProblem, readMission, missionTimes, TASK_KIND_KEYS, MISSION_RULES } from '../src/mission.js';
import { CELLS } from '../src/config.js';
import { MISSION } from '../src/demo-crew.js';
import { MISSION_CALENDAR, nextUp } from '../src/support.js';
import { exampleEarlierRuns } from '../src/reaction-test.js';
import { eventProblem, cleanEvent } from '../src/security.js';

const HOUR = 3600 * 1000;
const DAY = 24 * HOUR;
const START = Date.parse('2026-11-16T08:00:00Z');
const task = { id: 't1', kind: 'spacewalk', title: 'Spacewalk', start: new Date(START).toISOString(), crew: null, example: false };
const at = (h) => new Date(START + h * HOUR).toISOString(); // hours relative to the start, negative before it
const NOW = at(-10);
const KIT = CELLS.find((c) => c.indicator === 'medicines').kit;
const dose = (key, h, extra = {}) => { const k = KIT.find((x) => x.key === key); return { time: at(h), value: { medicine: k.key, name: k.name, strength: k.strength, amount: 1, unit: k.unit, ...extra } }; };
const run = (h, median, mode = 'full') => ({ time: at(h), median, mode, lapses: 1, falseStarts: 0, count: 60, durationS: mode === 'demo' ? 30 : 180, score: 98 });
const LONG_DASHES = /[\u2013\u2014]/;

test('the example holds a spacewalk, robotic arm work and a docking, made up, between today and landing, each with its crew', () => {
  assert.deepEqual(EXAMPLE_TASKS.map((t) => t.kind).sort(), ['docking', 'robotics', 'spacewalk']);
  const known = new Set(['crew-1', 'crew-2', 'crew-3', 'crew-4']);
  for (const t of EXAMPLE_TASKS) {
    assert.ok(t.day > 167 && t.day < 193, `${t.id}: after the example's flight day 167, before landing on day 193`);
    assert.ok(Number.isInteger(t.hour) && t.hour >= 0 && t.hour < 24, t.id);
    assert.ok(t.crew === null || (t.crew.length && t.crew.every((id) => known.has(id))), t.id);
    assert.ok(TASK_KINDS[t.kind], t.id);
  }
  const dated = exampleTasks(MISSION.launch);
  for (const [i, t] of dated.entries()) {
    assert.equal(t.example, true);
    assert.equal(Date.parse(t.start), Date.parse(MISSION.launch) + (EXAMPLE_TASKS[i].day - 1) * DAY + EXAMPLE_TASKS[i].hour * HOUR);
    assert.ok(Date.parse(t.start) < Date.parse(MISSION.landing));
  }
  // The spacewalk falls in the readiness window of the example's today, for the two who go out and nobody else.
  const now = MISSION.today;
  for (const id of ['crew-1', 'crew-2']) assert.equal(nextTask(tasksFor(dated, id), now).kind, 'spacewalk', id);
  for (const id of ['crew-1', 'crew-2']) assert.equal(readinessDue(nextTask(tasksFor(dated, id), now), now), true, id);
  for (const id of ['crew-3', 'crew-4']) assert.equal(readinessDue(nextTask(tasksFor(dated, id), now), now), false, id);
});

test('the tasks join the mission calendar as critical tasks, and the calendar line of Coming up stays as it was', () => {
  const items = calendarItems();
  assert.equal(items.length, EXAMPLE_TASKS.length);
  for (const x of items) {
    assert.equal(x.kind, 'task');
    assert.equal(x.example, true);
    assert.match(x.title, /\(critical task\)$/);
    assert.ok(x.icon && x.phrase);
  }
  assert.equal(nextUp(167, [...MISSION_CALENDAR, ...items]), 'Coming up: a spacewalk on flight day 168.');
  assert.equal(nextUp(167), 'Coming up: a message from home opens on flight day 170.', 'the default calendar is unchanged');
});

test('one person\'s tasks in time order, the next one, the next 14 days, and the 24-hour window of the card (drafts)', () => {
  const tasks = [
    { id: 'b', kind: 'docking', start: at(30), crew: null },
    { id: 'a', kind: 'robotics', start: at(2), crew: ['crew-3'] },
    { id: 'c', kind: 'spacewalk', start: at(-1), crew: null },
    { id: 'd', kind: 'other', start: at(20 * 24), crew: null },
  ];
  assert.deepEqual(tasksFor(tasks, 'crew-1').map((t) => t.id), ['c', 'b', 'd']);
  assert.deepEqual(tasksFor(tasks, 'crew-3').map((t) => t.id), ['c', 'a', 'b', 'd']);
  assert.equal(nextTask(tasksFor(tasks, 'crew-1'), at(0)).id, 'b', 'a task that has started is not next');
  assert.deepEqual(upcomingTasks(tasks, at(0)).map((t) => t.id), ['a', 'b'], `only the next ${READINESS_RULES.listDays} days`);
  assert.equal(READINESS_RULES.windowHours, 24);
  assert.equal(readinessDue({ start: at(0) }, at(-24)), true, 'exactly 24 hours before');
  assert.equal(readinessDue({ start: at(0) }, at(-24 - 1 / 60)), false, 'a minute earlier');
  assert.equal(readinessDue({ start: at(0) }, at(0)), false, 'gone once the task starts');
  assert.equal(readinessDue(null, at(0)), false);
});

test('last night: 6 hours or less is a short night (a draft after Jones et al. 2022); more is not; nothing in 24 hours says so', () => {
  const sleep = (h, hours) => [{ time: at(h), value: hours }];
  assert.equal(readiness({ task, now: NOW, sleep: sleep(-12, 6) }).sleep.state, 'short');
  assert.equal(readiness({ task, now: NOW, sleep: sleep(-12, 5.2) }).sleep.level, 1);
  const ok = readiness({ task, now: NOW, sleep: sleep(-12, 6.1) });
  assert.equal(ok.sleep.state, 'ok');
  assert.equal(ok.sleep.level, 0);
  assert.equal(readiness({ task, now: NOW, sleep: sleep(-40, 4) }).sleep.state, 'none', 'older than 24 hours is not last night');
  const newest = readiness({ task, now: NOW, sleep: [{ time: at(-36), value: 4 }, { time: at(-12), value: 7.5 }], quality: [{ time: at(-12), value: 3 }] });
  assert.equal(newest.sleep.hours, 7.5);
  assert.equal(newest.sleep.rating, 3);
  assert.equal(READINESS_RULES.shortNightHours, 6);
});

test('medicines: the kit list\'s sleep medicines and those with its sedation note count in the window; others do not', () => {
  const r = readiness({ task, now: NOW, medicines: [dose('ibuprofen', -12), dose('melatonin', -30), dose('meclizine', -18), dose('zolpidem', -20)] });
  assert.deepEqual(r.medicines.list.map((m) => m.key), ['zolpidem', 'meclizine'], 'melatonin 30 hours before is outside; ibuprofen is not sleepy');
  assert.equal(r.medicines.level, 1);
  const mec = r.medicines.list.find((m) => m.key === 'meclizine');
  assert.equal(mec.sedating, true);
  assert.equal(mec.hoursBefore, 18);
  assert.match(medicineText(mec), /"May cause sedation and impair performance\. Do not use with sleep meds\."/);
  // The time it was taken wins over the time it was logged.
  const late = readiness({ task, now: NOW, medicines: [{ ...dose('zolpidem', -11), value: { ...dose('zolpidem', -11).value, takenAt: at(-26) } }] });
  assert.equal(late.medicines.state, 'none', 'taken 26 hours before the start, logged later');
  // Zolpidem: its FDA label asks for at least 8 hours before work that needs full alertness.
  const near = readiness({ task, now: at(-1), medicines: [dose('zolpidem', -6)] }).medicines.list[0];
  assert.equal(near.underLabel, true);
  assert.match(medicineText(near), /less than the 8 hours its FDA label asks for/);
  assert.equal(readiness({ task, now: NOW, medicines: [dose('zolpidem', -12)] }).medicines.list[0].underLabel, false);
  assert.equal(READINESS_RULES.labelHours, 8);
});

test('the kit list\'s sedation note is data: exactly the medicines whose note says so are marked sedating', () => {
  for (const k of KIT) assert.equal(Boolean(k.sedating), /^May cause sedation and impair performance\./.test(k.kitNote || ''), k.key);
  assert.deepEqual(KIT.filter((k) => k.sleepMed).map((k) => k.key).sort(), ['melatonin', 'zolpidem']);
  assert.deepEqual(KIT.filter((k) => k.sedating).map((k) => k.key).sort(), ['meclizine', 'promethazine']);
});

test('the reaction test: the newest run of the window against the person\'s own runs; slower is attention; made-up runs are called made up', () => {
  const earlier = exampleEarlierRuns(Date.parse('2026-06-01T12:00:00Z'));
  const slow = readiness({ task, now: NOW, runs: [...earlier, run(-15, 330), run(-11, 360)] });
  assert.equal(slow.reaction.run.median, 360, 'the newest run');
  assert.equal(slow.reaction.state, 'slower');
  assert.equal(slow.reaction.level, 1);
  assert.match(slow.reaction.compare.text, /made-up example/);
  const same = readiness({ task, now: NOW, runs: [...earlier, run(-11, 306)] });
  assert.equal(same.reaction.state, 'similar');
  assert.equal(same.reaction.level, 0);
  assert.equal(readiness({ task, now: NOW, runs: [...earlier, run(-30, 400)] }).reaction.state, 'none', 'a run before the window does not count');
  assert.equal(readiness({ task, now: NOW, runs: [run(-11, 300, 'demo')] }).reaction.state, 'first', 'a first demo has nothing to compare with');
});

test('a short night or a sleep medicine asks for the reaction test until a run follows; the card is never more than attention', () => {
  const night = [{ time: at(-12), value: 5 }];
  assert.equal(readiness({ task, now: NOW, sleep: night }).askTest, true);
  assert.equal(readiness({ task, now: NOW, medicines: [dose('melatonin', -14)] }).askTest, true);
  assert.equal(readiness({ task, now: NOW, sleep: [{ time: at(-12), value: 7 }] }).askTest, false);
  assert.equal(readiness({ task, now: NOW, sleep: night, runs: [run(-11, 305)] }).askTest, false, 'a run after the night');
  assert.equal(readiness({ task, now: NOW, medicines: [dose('zolpidem', -10.5)], runs: [run(-11, 305)] }).askTest, true, 'the run came before the dose');
  const worst = readiness({ task, now: NOW, sleep: night, medicines: [dose('zolpidem', -12)], runs: [...exampleEarlierRuns(Date.parse('2026-06-01T12:00:00Z')), run(-11, 420)] });
  assert.equal(worst.level, 1, 'attention at most');
  assert.equal(worst.draft, true);
});

test('plain words: every line names its sources, the drafts say so, nothing claims to be sent, and there are no long dashes', () => {
  const r = readiness({ task, now: at(-1), sleep: [{ time: at(-12), value: 5 }], medicines: [dose('zolpidem', -6), dose('melatonin', -9), dose('promethazine', -15)], runs: [run(-2, 330)] });
  const lines = readinessLines(r);
  assert.deepEqual(lines.map((l) => l.key), ['sleep', 'medicines', 'reaction']);
  for (const l of lines) {
    assert.ok(l.title && l.text, l.key);
    for (const s of l.src) assert.match(s.url, /^https:\/\//, `${l.key}: ${s.name}`);
    assert.ok(!LONG_DASHES.test(l.title + l.text), l.key);
    assert.ok(!/\bwas sent\b|\bsent to\b|\bhas been sent\b/i.test(l.text), l.key);
  }
  assert.match(lines[0].text, /a draft/);
  assert.match(lines[1].text, /a draft rule/);
  assert.match(lines[1].text, /Its FDA label says: "Tell patients to wait for at least 8 hours after dosing before driving or engaging in other activities requiring full mental alertness\."/);
  assert.match(lines[1].text, /dietary supplement, regulated less strictly by the FDA/);
  assert.ok(lines[1].src.includes(READINESS_SOURCES.zolpidem) && lines[1].src.includes(READINESS_SOURCES.melatonin));
  for (const n of Object.values(MEDICINE_NOTES)) assert.ok(!LONG_DASHES.test(n.text));
  const msg = readinessMessage({ ...r, task: { ...task, example: true } }, { name: 'Elly', when: startsIn(r.hoursTo) });
  assert.match(msg, /^Before the spacewalk \(a made-up example task\), which starts GMT \d+\/\d\d:\d\d \(in 1 hour\), from Elly's readiness card:/);
  assert.match(msg, /does not decide whether I do the task/);
  assert.ok(!LONG_DASHES.test(msg));
  assert.equal(startsIn(0.5), 'in 30 minutes');
  assert.equal(startsIn(14.2), 'in 14 hours');
  assert.equal(startsIn(80), 'in 3 days');
  // Coming up shows the GMT date next to it, so from 2 days on it counts GMT calendar days: 7 days and 16 hours after
  // 15 Nov 07:00 is 22 Nov, "in 7 days", not "in 8 days".
  assert.equal(startsInAt('2026-11-22T23:00:00Z', '2026-11-15T07:00:00Z'), 'in 7 days');
  assert.equal(startsInAt('2026-11-16T03:00:00Z', '2026-11-15T07:00:00Z'), 'in 20 hours');
  assert.equal(taskName({ kind: 'robotics' }), 'Robotic arm work');
  assert.equal(taskThe({ kind: 'other', title: 'Hatch opening' }), 'the task "Hatch opening"');
});

test('the rules are drafts and their sources are public links', () => {
  assert.equal(READINESS_RULES.draft, true);
  for (const s of Object.values(READINESS_SOURCES)) assert.match(s.url, /^https:\/\//, s.name);
  assert.match(READINESS_SOURCES.jones2022.url, /PMC8919197/);
  assert.match(READINESS_SOURCES.zolpidem.url, /dailymed\.nlm\.nih\.gov/);
  assert.deepEqual(Object.keys(TASK_KINDS).sort(), [...TASK_KIND_KEYS].sort(), 'the kinds the mission can hold are the kinds the card knows');
});

test('the crew\'s own mission holds critical tasks between launch and landing; a mission saved before still reads the same', () => {
  const m = { name: 'HERA C7', launch: '2026-11-01', landing: '2026-12-15' };
  assert.equal(taskProblem({ kind: 'spacewalk', title: '', date: '2026-11-20', time: '13:30' }, m), null);
  assert.match(taskProblem({ kind: 'party', date: '2026-11-20', time: '13:30' }, m), /kind/);
  assert.match(taskProblem({ kind: 'docking', date: '2026-11-31', time: '13:30' }, m), /date/);
  assert.match(taskProblem({ kind: 'docking', date: '2026-11-20', time: '25:00' }, m), /start time/);
  assert.match(taskProblem({ kind: 'docking', date: '2026-12-16', time: '10:00' }, m), /between launch and landing/);
  assert.match(taskProblem({ kind: 'other', title: 'x'.repeat(MISSION_RULES.taskNameMax + 1), date: '2026-11-20', time: '10:00' }, m), /at most/);
  const saved = readMission({ ...m, tasks: [
    { kind: 'docking', title: ' Crew ship ', date: '2026-11-22', time: '04:00' },
    { kind: 'spacewalk', date: '2026-11-20', time: '13:30' },
    { kind: 'robotics', date: '2027-01-01', time: '10:00' },
    'junk',
  ] });
  assert.deepEqual(saved.tasks, [
    { kind: 'spacewalk', title: '', date: '2026-11-20', time: '13:30' },
    { kind: 'docking', title: 'Crew ship', date: '2026-11-22', time: '04:00' },
  ], 'in time order, trimmed, the task after landing and the junk left out');
  assert.deepEqual(readMission(m), m, 'no tasks: the same shape as before');
  const many = readMission({ ...m, tasks: Array.from({ length: MISSION_RULES.tasksMax + 5 }, (_, i) => ({ kind: 'other', date: '2026-11-20', time: `${String(i % 24).padStart(2, '0')}:00` })) });
  assert.equal(many.tasks.length, MISSION_RULES.tasksMax);
  const times = missionTimes(saved, Date.parse('2026-11-19T12:00:00Z'));
  assert.deepEqual(times.tasks.map((t) => t.start), ['2026-11-20T13:30:00Z', '2026-11-22T04:00:00Z']);
  assert.ok(times.tasks.every((t) => t.example === false && t.crew === null));
  assert.equal(readinessDue(nextTask(times.tasks, '2026-11-19T20:00:00Z'), '2026-11-19T20:00:00Z'), true);
});

test('the message to the flight surgeon passes the server\'s check with the topic "readiness", and the checked copy keeps it', () => {
  const now = new Date();
  const r = readiness({ task: { ...task, start: new Date(now.getTime() + 10 * HOUR).toISOString() }, now, sleep: [{ time: new Date(now.getTime() - 2 * HOUR).toISOString(), value: 5.5 }] });
  const ev = { v: 1, kind: 'report', time: now.toISOString(), person: 'crew-2', state: { aiWorks: true, doctorOnBoard: false, linkToEarth: true }, report: { to: 'doctor-earth', text: readinessMessage(r, { name: 'Elly' }), topic: 'readiness' } };
  assert.equal(eventProblem(ev, { now }), null);
  assert.equal(cleanEvent(ev).report.topic, 'readiness');
  assert.ok(readinessMessage(r).length <= 4000, 'fits the message box of the crew screen');
});

test('the new files carry their SI note and no long dashes', () => {
  for (const f of ['src/readiness.js', 'src/landing.js', 'src/mission-cards.js', 'tests/readiness.test.js', 'tests/landing.test.js']) {
    const text = readFileSync(new URL(`../${f}`, import.meta.url), 'utf8');
    assert.ok(!LONG_DASHES.test(text), `${f}: no long dashes`);
    const header = text.slice(0, text.indexOf('\nimport ') > 0 ? text.indexOf('\nimport ') : 3000);
    assert.match(header, /Code generated by Claude \(Anthropic\), an AI system\./, f);
  }
});
